-- ===== Is'hoqxon Ibrat =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Исхакхан Ибрат?', fact_ru = 'Я родился в 1862 году в селении Туракурган близ Намангана.' WHERE id = 281;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'В каком медресе учился Исхакхан Ибрат?', fact_ru = 'Сперва я учился в старой школе, затем в кокандском медресе и окончил его в 1886 году.' WHERE id = 282;
UPDATE fact_cards SET topic_ru = 'Моё большое путешествие', question_ru = 'В каких городах побывал Исхакхан Ибрат во время своего путешествия?', fact_ru = 'В 1887 году я отправился в хадж и побывал в Стамбуле, Софии, Афинах и Риме; затем жил в Джидде, Бомбее и Калькутте.' WHERE id = 283;
UPDATE fact_cards SET topic_ru = 'Мои языки', question_ru = 'Какие языки изучил Исхакхан Ибрат?', fact_ru = 'В своих странствиях я в совершенстве изучил арабский, персидский, хинди-урду и английский языки.' WHERE id = 284;
UPDATE fact_cards SET topic_ru = 'Возвращение на родину', question_ru = 'Когда Исхакхан Ибрат вернулся на родину?', fact_ru = 'В 1896 году я вернулся на родину.' WHERE id = 285;
UPDATE fact_cards SET topic_ru = 'Мой словарь на шести языках', question_ru = 'Как называется шестиязычный словарь Исхакхана Ибрата?', fact_ru = 'В 1901 году я издал свой шестиязычный словарь «Лугати ситта альсина» — из арабских, персидских, индийских, турецких, узбекских и русских слов.' WHERE id = 286;
UPDATE fact_cards SET topic_ru = 'Моя школа', question_ru = 'Где Исхакхан Ибрат открыл школу нового метода?', fact_ru = 'В 1907 году я открыл в Туракургане школу нового метода.' WHERE id = 287;
UPDATE fact_cards SET topic_ru = 'Моя типография', question_ru = 'Какую типографию устроил Исхакхан Ибрат?', fact_ru = 'В 1908 году я устроил в своём селении литографскую типографию «Матбааи Исхакия».' WHERE id = 288;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'Как называется труд Исхакхана Ибрата по истории письменности?', fact_ru = 'В 1909 году вышел мой поэтический сборник «Ильми Ибрат», а в 1912 году я создал труд «Джоме уль-хутут» по истории письменностей.' WHERE id = 289;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'В каком возрасте умер Исхакхан Ибрат?', fact_ru = 'Я скончался в 1937 году, на 75-м году жизни, в андижанской тюрьме.' WHERE id = 290;
UPDATE fact_cards SET topic_ru = 'Мой псевдоним «Ибрат»', question_ru = 'Что означает псевдоним «Ибрат» Исхакхана-туры?', fact_ru = 'Моё настоящее имя — Исхакхан. «Ибрат» — мой псевдоним, он означает «урок, образец».' WHERE id = 1650;
UPDATE fact_cards SET topic_ru = 'Моя служба казием', question_ru = 'В какой должности служил Исхакхан Ибрат в своём краю, Туракургане?', fact_ru = 'В родном Туракургане я служил казием. Я старался разрешать людские тяжбы по справедливости.' WHERE id = 1651;
UPDATE fact_cards SET topic_ru = 'Моя книга «Джоме уль-хутут»', question_ru = 'О чём труд Исхакхана Ибрата «Джоме уль-хутут»?', fact_ru = 'В своей книге «Джоме уль-хутут» я изложил историю письменностей народов мира. Эту книгу я напечатал в собственной типографии.' WHERE id = 1652;
UPDATE fact_cards SET topic_ru = '«История Ферганы»', question_ru = 'В каком труде Исхакхан Ибрат осветил историю Ферганской долины?', fact_ru = 'В труде «История Ферганы» я записал прошлое родной мне Ферганской долины.' WHERE id = 1653;
UPDATE fact_cards SET topic_ru = 'Мои статьи в газетах', question_ru = 'В какой газете печатались статьи Исхакхана Ибрата?', fact_ru = 'Мои статьи печатались в таких изданиях, как «Туркистон вилоятининг газети». В них я призывал народ к науке и просвещению.' WHERE id = 1654;
UPDATE fact_cards SET topic_ru = 'Моё поэтическое творчество', question_ru = 'К чему призывал молодёжь Исхакхан Ибрат в своих стихах?', fact_ru = 'Писал я и стихи: в них я призывал детей и молодёжь получать знания, овладевать ремеслом.' WHERE id = 1655;
UPDATE fact_cards SET topic_ru = 'Мой дом-музей', question_ru = 'Где находится музей, посвящённый памяти Исхакхана Ибрата?', fact_ru = 'Сегодня в Туракургане действует музей, посвящённый моей памяти. Школы и улицы в моём краю тоже носят моё имя.' WHERE id = 1656;

-- ===== Ubaydulla Xo'jayev =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Убайдулла Ходжаев?', fact_ru = 'Я родился в 1878 году в Ташкенте, в семье садовника.' WHERE id = 291;
