UPDATE fact_cards SET topic_ru = 'Служение народу', question_ru = 'Чем остался в истории Убайдулла Ходжаев?', fact_ru = 'В 1913 году я вернулся в Ташкент и служил народу как адвокат — я был одним из первых узбекских адвокатов.' WHERE id = 294;
UPDATE fact_cards SET topic_ru = '«Садои Туркистон»', question_ru = 'Когда начала выходить газета «Садои Туркистон»?', fact_ru = 'В апреле 1914 года мы с соратниками начали выпускать газету «Садои Туркистон».' WHERE id = 295;
UPDATE fact_cards SET topic_ru = 'Расходы на газету', question_ru = 'Когда была закрыта газета «Садои Туркистон»?', fact_ru = 'Каждый номер газеты выходил в убыток — расходы я взял на себя. В 1915 году газета была закрыта.' WHERE id = 296;
UPDATE fact_cards SET topic_ru = 'Авторы моей газеты', question_ru = 'Кто участвовал на страницах «Садои Туркистон»?', fact_ru = 'На страницах моей газеты участвовали Абдулла Авлони и другие просветители, печатались и первые опыты юного Чулпана.' WHERE id = 297;
UPDATE fact_cards SET topic_ru = '1917 год', question_ru = 'Председателем какого общества стал Убайдулла Ходжаев в 1917 году?', fact_ru = 'В 1917 году я был избран председателем ташкентского общества «Шурои ислом».' WHERE id = 298;
UPDATE fact_cards SET topic_ru = 'Автономия', question_ru = 'В строительстве какого государства участвовал Убайдулла Ходжаев?', fact_ru = 'Я участвовал в делах Туркестанской автономии.' WHERE id = 299;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Убайдулла Ходжаев?', fact_ru = 'В 1938 году я был взят под стражу, а в 1939 году умер в ссылке.' WHERE id = 300;
UPDATE fact_cards SET topic_ru = 'Моё полное имя', question_ru = 'Каким было полное имя Убайдуллы Ходжаева?', fact_ru = 'Моё полное имя — Убайдуллаходжа Асадуллаходжаев. В истории меня чаще упоминают под именем Убайдулла Ходжаев.' WHERE id = 1807;
UPDATE fact_cards SET topic_ru = 'Мой путь джадида', question_ru = 'Представителем какого просветительского движения был Убайдулла Ходжаев?', fact_ru = 'Я был в рядах туркестанских джадидов: я стремился пробудить свой народ через школы нового метода, печать и просвещение.' WHERE id = 1808;
UPDATE fact_cards SET topic_ru = 'Общество «Турон»', question_ru = 'Одним из основателей какого просветительского общества в Ташкенте был Убайдулла Ходжаев?', fact_ru = 'Я один из учредителей общества «Турон», созданного в Ташкенте в 1913 году. Это общество занималось театром и делом просвещения.' WHERE id = 1809;
UPDATE fact_cards SET topic_ru = 'События мардикорства', question_ru = 'Как Убайдулла Ходжаев защищал своих земляков в событиях мардикорства 1916 года?', fact_ru = 'В событиях набора на тыловые работы 1916 года я защищал права своих земляков: я поехал в Петербург и донёс положение Туркестана до мусульманской фракции Государственной думы.' WHERE id = 1810;
UPDATE fact_cards SET topic_ru = '«Шурои Исламия»', question_ru = 'Председателем какой организации был избран Убайдулла Ходжаев в 1917 году?', fact_ru = 'В марте 1917 года я был избран председателем организации «Шурои Исламия», созданной в Ташкенте.' WHERE id = 1811;
UPDATE fact_cards SET topic_ru = 'Военное ведомство', question_ru = 'Какую должность занимал Убайдулла Ходжаев в правительстве Туркестанской автономии?', fact_ru = 'В правительстве Туркестанской автономии мне была доверена должность министра по военным делам.' WHERE id = 1812;
UPDATE fact_cards SET topic_ru = 'Память', question_ru = 'Как сегодня вспоминают имя Убайдуллы Ходжаева в Узбекистане?', fact_ru = 'Сегодня в Узбекистане моё имя с почтением упоминают в ряду джадидов-просветителей, а мою жизнь и деятельность изучают в учебниках истории.' WHERE id = 1813;

-- ===== Ozod Sharafiddinov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Озод Шарафиддинов?', fact_ru = 'Я родился 1 марта 1929 года в селении Ахункайнар близ Коканда.' WHERE id = 596;
UPDATE fact_cards SET topic_ru = 'Мой путь в науке', question_ru = 'Когда Озод Шарафиддинов получил звание профессора?', fact_ru = 'В 1951 году я окончил Среднеазиатский университет, в 1954 году стал кандидатом филологических наук, а в 1979 году получил звание профессора.' WHERE id = 597;
UPDATE fact_cards SET topic_ru = 'Сорок лет наставничества', question_ru = 'Сколько лет Озод Шарафиддинов преподавал в университете?', fact_ru = 'С 1955 по 1995 год — сорок лет — я был доцентом и профессором факультета узбекской филологии Ташкентского государственного университета и открывал студентам тайны литературы.' WHERE id = 598;
UPDATE fact_cards SET topic_ru = 'Моя первая известная книга', question_ru = 'Как называется первая известная книга Озода Шарафиддинова?', fact_ru = 'В вышедшей в 1962 году книге «Время. Сердце. Поэзия» я разобрал поэзию по мерилам художественности; затем были изданы мои книги «Литературные этюды», «Первое чудо», «В одном дыхании с жизнью».' WHERE id = 599;
UPDATE fact_cards SET topic_ru = 'Постижение Чулпана', question_ru = 'Что сделал Озод Шарафиддинов в труде «Постижение Чулпана»?', fact_ru = 'В 1993 году я написал труд «Постижение Чулпана» — изучив творчество великого поэта Чулпана, запрещённого в годы репрессий, я внёс свой вклад в то, чтобы вновь представить его читателям.' WHERE id = 600;
UPDATE fact_cards SET topic_ru = 'Моё переводческое дело', question_ru = 'Каких мировых писателей перевёл на узбекский Озод Шарафиддинов?', fact_ru = 'Я перевёл на узбекский язык произведения таких мировых писателей, как Лев Толстой и Пауло Коэльо, — я из тех, кто начал традицию изучать узбекскую литературу в связи с мировой.' WHERE id = 601;
UPDATE fact_cards SET topic_ru = 'Журнал «Жахон адабиёти»', question_ru = 'Какого журнала Озод Шарафиддинов был главным редактором?', fact_ru = 'В 1996–1997 годах я был заместителем главного редактора журнала «Тафаккур», а с 1997 года — главным редактором журнала «Жахон адабиёти».' WHERE id = 602;
UPDATE fact_cards SET topic_ru = 'Автор учебника', question_ru = 'Когда Озод Шарафиддинов получил Государственную премию имени Беруни?', fact_ru = 'В 1970 году я получил Государственную премию Узбекистана имени Беруни, а также я один из авторов вышедшего в 1999 году учебника «История литературы Узбекистана».' WHERE id = 603;
UPDATE fact_cards SET topic_ru = 'Герой Узбекистана', question_ru = 'Когда Озод Шарафиддинов получил звание Героя Узбекистана?', fact_ru = 'В 2002 году мне было присвоено звание «Герой Узбекистана» — это была наивысшая оценка моих трудов.' WHERE id = 604;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Озод Шарафиддинов?', fact_ru = 'Я скончался в 2005 году в Ташкенте.' WHERE id = 605;
UPDATE fact_cards SET topic_ru = 'Моё ремесло критика', question_ru = 'Каким было главное занятие Озода Шарафиддинова?', fact_ru = 'Моё ремесло — литературный критик. Я изучал произведения писателей и поэтов и писал о них статьи и книги.' WHERE id = 1765;
UPDATE fact_cards SET topic_ru = 'Поэзия — моя главная тема', question_ru = 'Что более всего изучал Озод Шарафиддинов в своих научных работах?', fact_ru = 'В своих научных работах я более всего изучал современную узбекскую поэзию. Я написал множество статей о том, каким должно быть хорошее стихотворение.' WHERE id = 1766;
UPDATE fact_cards SET topic_ru = 'Моя поддержка молодых поэтов', question_ru = 'Творчество каких молодых поэтов поддерживал Озод Шарафиддинов?', fact_ru = 'Я писал тёплые статьи о творчестве таких молодых поэтов, как Эркин Вахидов и Абдулла Арипов, и помог им стать известными народу.' WHERE id = 1767;
UPDATE fact_cards SET topic_ru = 'Мои сборники статей', question_ru = 'В каких книгах Озода Шарафиддинова собраны его литературно-критические статьи?', fact_ru = 'Мои статьи о литературе собраны в таких книгах, как «Литературные этюды» и «Талант — достояние народа».' WHERE id = 1768;
UPDATE fact_cards SET topic_ru = '«Тяготы постижения творчества»', question_ru = 'Какую книгу издал Озод Шарафиддинов в последние годы жизни?', fact_ru = 'В последние годы жизни я издал большую книгу под названием «Тяготы постижения творчества». В неё вошли мои лучшие статьи и эссе.' WHERE id = 1769;
UPDATE fact_cards SET topic_ru = 'Мой перевод «Алхимика»', question_ru = 'Какое знаменитое произведение мировой литературы перевёл на узбекский Озод Шарафиддинов?', fact_ru = 'Знаменитое произведение бразильского писателя Пауло Коэльо «Алхимик» перевёл на узбекский язык я.' WHERE id = 1770;
UPDATE fact_cards SET topic_ru = 'Моя стойкость', question_ru = 'Продолжал ли Озод Шарафиддинов работать, когда его настигла тяжёлая болезнь?', fact_ru = 'В конце жизни меня настигла тяжёлая болезнь, но творчества я не оставил. Даже сидя в инвалидной коляске, я руководил журналом, работал над переводами и статьями.' WHERE id = 1771;
